package com.yuegang.zhihui.wallet.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.wallet.api.*;import java.math.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;
public final class WalletService{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public WalletService(DataSource d){jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public WalletView get(long user){ensure(user,"CNY");return jdbc.query("SELECT available_balance,frozen_balance,currency,version FROM wallet_account WHERE user_id=?",r->{r.next();return new WalletView(Long.toString(user),r.getBigDecimal(1),r.getBigDecimal(2),r.getString(3),r.getLong(4));},user);}public WalletTransactionView recharge(long user,WalletCommand c){return change(user,c,"RECHARGE",c.amount(),"WALLET_RECHARGE_SUCCEEDED");}public WalletTransactionView pay(long user,WalletCommand c){return change(user,c,"PAYMENT",c.amount().negate(),"WALLET_PAYMENT_SUCCEEDED");}public WalletTransactionView refund(long user,WalletCommand c){return change(user,c,"REFUND",c.amount(),"WALLET_REFUND_SUCCEEDED");}private WalletTransactionView change(long user,WalletCommand c,String type,BigDecimal delta,String event){return tx.execute(s->{ensure(user,c.currency());var existing=find(c.requestId());if(existing!=null)return existing;var before=jdbc.queryForObject("SELECT available_balance FROM wallet_account WHERE user_id=? FOR UPDATE",BigDecimal.class,user);if(delta.signum()<0&&before.compareTo(delta.abs())<0)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);var after=before.add(delta);jdbc.update("UPDATE wallet_account SET available_balance=?,version=version+1 WHERE user_id=?",after,user);long id=next();jdbc.update("INSERT INTO wallet_transaction(id,request_id,user_id,type,status,amount,currency,reference_id,balance_before,balance_after,completed_at) VALUES(?,?,?,?, 'SUCCEEDED',?,?,?,?,?,NOW(6))",id,c.requestId(),user,type,c.amount(),c.currency(),c.referenceId(),before,after);String eventId=UUID.randomUUID().toString();jdbc.update("INSERT INTO wallet_outbox(id,aggregate_id,event_type,payload_json) VALUES(?,?,?,JSON_OBJECT('eventId',?,'userId',?,'referenceId',?,'amount',?,'currency',?))",eventId,Long.toString(user),event,eventId,Long.toString(user),c.referenceId(),c.amount(),c.currency());return find(c.requestId());});}private void ensure(long user,String currency){jdbc.update("INSERT INTO wallet_account(user_id,currency) VALUES(?,?) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id)",user,currency);}private WalletTransactionView find(String request){return jdbc.query("SELECT id,type,status,amount,currency,reference_id,created_at FROM wallet_transaction WHERE request_id=?",r->r.next()?new WalletTransactionView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getString(5),r.getString(6),r.getTimestamp(7).toLocalDateTime().atOffset(ZoneOffset.UTC)):null,request);}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
